WITH hamilton AS (
    SELECT drv_main FROM drivers WHERE driver_identity->>'surname' = 'Hamilton' AND driver_identity->>'first_name' = 'Lewis'
),
hamilton_age AS (
    SELECT FLOOR((CURRENT_DATE - (d.driver_identity->>'birth_date')::date) / 365.25)::numeric AS age
    FROM drivers d CROSS JOIN hamilton h WHERE d.drv_main = h.drv_main
)
SELECT * FROM hamilton_age;

